tasks.solution:
using System;
using System.Collections.Generic;

class Program
{
    static string SecondsToTime(int sec)
    {
        int hours = sec / 3600;
        int rest = sec % 3600;
        int minutes = rest / 60;
        int seconds = rest % 60;
        return hours + " ч " + minutes + " мин " + seconds + " с";
    }
}
